'use strict';
const A=document.getElementById('admin-root'),E=document.getElementById('editor'),eb=document.getElementById('editor-body');const h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const inr=n=>'₹'+Number(n||0).toLocaleString('en-IN');let period=7,query='',month=new Date().getMonth(),year=new Date().getFullYear(),uploaded='',chartMode='line',metric='revenue';
const NAV=[['Workspace',[['dashboard','Dashboard','▦'],['analytics','Analytics','◴'],['visitors','Live Visitors','◉'],['calendar','Calendar','▦']]],['Commerce',[['orders','Orders','▤'],['prescriptions','Prescriptions & quotes','▤'],['returns','Returns','↩'],['products','Products','◇'],['inventory','Inventory','▧'],['discounts','Discounts','%'],['customers','Customers','♙']]],['Growth',[['consultations','Doctor services','✚'],['appointments','Consultation requests','♡'],['offers','Store offers','%'],['marketing','Marketing','↗'],['behaviour','Customer Behaviour','⌁']]],['Content',[['banners','Banners','▣'],['media','Photo Library','▧'],['images','Site Images','▨'],['editor','Store Editor','⚑']]],['Platform',[['settings','Settings','⚙'],['audit','Activity log','☷']]]];
const SCHEMAS={consultations:[['name','Service name','text'],['specialty','Specialty','text'],['description','Description','textarea'],['fee','Sample fee (₹)','number'],['duration','Duration (minutes)','number'],['languages','Languages','text'],['image','Image URL','image'],['active','Visible','checkbox']],offers:[['title','Offer title','text'],['description','Terms and description','textarea'],['code','Coupon code (optional)','text'],['image','Offer image','image'],['link','Destination','text'],['active','Visible','checkbox']],categories:[['id','Category key','text'],['name','Display name','text'],['type','Illustration','select',['bottle','tube','pump','cream','device','monitor','box']],['color','Colour (hex)','text'],['active','Visible','checkbox']],products:[['id','Product slug','text'],['name','Product name','text'],['sku','SKU','text'],['category','Category','select',['Vitamins','Personal care','Devices','Baby care','First aid','Everyday care']],['price','Selling price (₹)','number'],['mrp','MRP (₹)','number'],['stock','Stock quantity','number'],['pack','Pack description','text'],['description','Description','textarea'],['image','Product image URL','image'],['active','Visible in store','checkbox'],['prescription','Prescription required (enquiry only)','checkbox'],['medicine','Show in medicine catalogue','checkbox'],['brand','Brand name','text'],['manufacturer','Manufacturer / demo supplier','text'],['ingredient','Ingredient (optional)','text'],['strength','Strength (optional)','text'],['dosageForm','Dosage form (optional)','text'],['release','Release type (optional)','text'],['route','Route (optional)','text'],['variant','Formulation descriptor (optional)','text'],['packUnits','Units per pack','number'],['source','Manufacturer information URL (optional)','text']],discounts:[['code','Coupon code','text'],['type','Discount type','select',['percent','fixed']],['value','Discount value','number'],['minOrder','Minimum order (₹)','number'],['expires','Expiry date (optional)','date'],['active','Active','checkbox']],customers:[['name','Customer name','text'],['email','Email','email'],['phone','Phone (optional)','text'],['city','City','text'],['consent','Marketing opt-in recorded','checkbox']],banners:[['title','Banner title','text'],['subtitle','Supporting text','text'],['image','Image URL','image'],['placement','Placement','select',['hero','shop','promo','consult']],['link','Destination','text'],['active','Visible','checkbox']],campaigns:[['name','Campaign name','text'],['channel','Channel','select',['Email','WhatsApp','SMS']],['status','Status','select',['Draft','Scheduled','Paused']],['audience','Audience','text'],['message','Message','textarea'],['schedule','Planned date','date']],calendar:[['title','Event title','text'],['date','Date','date'],['type','Type','select',['Operations','Campaign','Stock','Follow-up']],['notes','Notes','textarea']],navigation:[['label','Menu label','text'],['href','Destination','text'],['active','Visible','checkbox']]};
const label=v=>`<span class="status ${['Delivered','Active','Approved','Refunded','Visible'].includes(v)?'green':['Pending','Requested','Scheduled','Processing'].includes(v)?'orange':['Cancelled','Rejected','Hidden'].includes(v)?'red':''}">${h(v)}</span>`;const date=v=>new Date(v).toLocaleDateString('en-IN',{day:'2-digit',month:'short'});const page=()=>location.hash.slice(2).split('?')[0]||'dashboard';
function notify(message){const e=document.getElementById('admin-toast');e.textContent=message;e.classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>e.classList.remove('show'),3500)}
function dialog(html){eb.innerHTML=html;E.showModal()}
function rangeOrders(){const cut=Date.now()-period*86400000;return Store.state.orders.filter(o=>new Date(o.created)>=cut)}
function revenue(orders){return orders.filter(o=>!['Cancelled','Refunded'].includes(o.status)).reduce((s,o)=>s+(+o.total||0),0)}
function stats(){const orders=rangeOrders(),rev=revenue(orders),live=Store.state.sessions.filter(s=>Date.now()-new Date(s.at)<90000).length;return [['Sample revenue',inr(rev),'Within selected range','↗'],['Demo orders',orders.length,'All payment amounts are illustrative','▤'],['Average order',inr(orders.length?Math.round(rev/orders.length):0),'Based on demo orders','◴'],['Low stock',Store.state.products.filter(p=>p.stock<15).length,'Products with fewer than 15 units','▧']].map(([title,value,sub,ico],i)=>`<article class="stat-card motion-card" role="button" tabindex="0" data-act="stat-go" data-route="${['analytics','orders','analytics','inventory'][i]}" aria-label="${title}: ${h(value)}. Open details."><div class="stat-top">${title}<span class="stat-icon">${ico}</span></div><strong>${value}</strong><small>${sub}</small><svg class="stat-line" viewBox="0 0 70 30" aria-hidden="true"><path d="M1 27 10 20 20 24 29 13 39 17 49 9 59 13 69 2" fill="none" stroke="#4d95c7" stroke-width="2"/></svg></article>`).join('')}
function lineChart(){const days=Array.from({length:period},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(period-1-i));return {key:d.toISOString().slice(0,10),label:d.toLocaleDateString('en-IN',{day:'2-digit',month:'short'})}});const sums=days.map(d=>{const orders=Store.state.orders.filter(o=>o.created.slice(0,10)===d.key);return metric==='orders'?orders.length:revenue(orders)}),max=Math.max(metric==='orders'?4:100,...sums),x=i=>48+i*568/Math.max(period-1,1),y=v=>182-v/max*143,format=v=>metric==='orders'?v+' demo orders':inr(v)+' demo revenue',hint=(v,i)=>h(days[i].label+' · '+format(v)),pointAttrs=(v,i)=>`class="interactive-point" tabindex="0" role="button" data-act="chart-day" data-day="${days[i].key}" data-chart-hint="${hint(v,i)}" aria-label="${hint(v,i)}. Open orders for this day."`;const points=sums.map((v,i)=>`${x(i)},${y(v)}`).join(' ');const barWidth=Math.min(40,420/period);return `<div class="chart-toolbar"><div class="chart-segments" role="group" aria-label="Chart display"><button data-act="chart-mode" data-mode="line" class="${chartMode==='line'?'active':''}" aria-pressed="${chartMode==='line'}">Area</button><button data-act="chart-mode" data-mode="bars" class="${chartMode==='bars'?'active':''}" aria-pressed="${chartMode==='bars'}">3D bars</button></div><select id="chart-metric" class="chart-metric" aria-label="Chart metric"><option value="revenue" ${metric==='revenue'?'selected':''}>Demo revenue</option><option value="orders" ${metric==='orders'?'selected':''}>Demo orders</option></select></div><svg class="chart" viewBox="0 0 650 220" role="img" aria-label="${metric==='orders'?'Demo orders':'Demo revenue'} by day, ${chartMode==='bars'?'bar':'area'} chart"><defs><linearGradient id="chartArea" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#6699f2" stop-opacity=".28"/><stop offset="1" stop-color="#6699f2" stop-opacity=".01"/></linearGradient><linearGradient id="barFront" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#73a3ff"/><stop offset="1" stop-color="#4e7ee5"/></linearGradient><linearGradient id="chartStroke"><stop stop-color="#50b5c6"/><stop offset=".5" stop-color="#5588eb"/><stop offset="1" stop-color="#8a7ddd"/></linearGradient></defs>${[0,1,2,3].map(i=>`<line x1="46" x2="628" y1="${39+i*47.5}" y2="${39+i*47.5}" stroke="#e3eaf5" stroke-dasharray="3 5"/><text x="0" y="${43+i*47.5}">${Math.round(max*(3-i)/3)}</text>`).join('')}${chartMode==='line'?`<polygon points="48,182 ${points} 616,182" fill="url(#chartArea)"/><polyline points="${points}" class="series-line" stroke="url(#chartStroke)" stroke-width="3" stroke-linejoin="round" stroke-linecap="round" fill="none"/>${sums.map((v,i)=>`<circle ${pointAttrs(v,i)} cx="${x(i)}" cy="${y(v)}" r="4.5" fill="#5a8be5" stroke="white" stroke-width="2"><title>${hint(v,i)}</title></circle>`).join('')}`:sums.map((v,i)=>{const cx=x(i),cy=y(v),w=barWidth,left=cx-w/2;return `<g ${pointAttrs(v,i)}><title>${hint(v,i)}</title><rect x="${left}" y="${cy}" width="${w}" height="${Math.max(1,182-cy)}" rx="2" fill="url(#barFront)"/><path d="M${left} ${cy}l6 -5h${w}l-6 5z" fill="#aac9ff"/><path d="M${left+w} ${cy}l6 -5v${Math.max(1,182-cy)}l-6 5z" fill="#426dc1"/></g>`}).join('')}${days.map((d,i)=>period<=7||i%5===0?`<text text-anchor="middle" x="${x(i)}" y="211">${d.label}</text>`:'').join('')}</svg><p class="chart-hint"><i></i>Hover, tap or focus for values. Select a point to view its orders.</p>`}
function donut(){const statuses=['Delivered','Processing','Shipped','Pending','Cancelled','Refunded'],colors=['#568feb','#46b6a4','#a18bdd','#efb177','#db91aa','#b49bcf'],orders=rangeOrders();let offset=0;return `<div class="donut-wrap"><svg viewBox="0 0 160 160" role="img" aria-label="Demo order statuses; select a segment to filter orders"><circle cx="80" cy="80" r="62" fill="none" stroke="#e6edf8" stroke-width="16"/>${statuses.map((s,i)=>{const n=orders.filter(o=>o.status===s).length,c=n/Math.max(orders.length,1)*389.55;const svg=`<circle cx="80" cy="80" r="62" fill="none" stroke="${colors[i]}" stroke-width="16" stroke-dasharray="${c} ${389.55-c}" stroke-dashoffset="${-offset}" tabindex="0" role="button" data-act="status-orders" data-status="${s}" data-chart-hint="${s} · ${n} demo orders" aria-label="View ${n} ${s.toLowerCase()} demo orders"><title>${s}: ${n}</title></circle>`;offset+=c;return svg}).join('')}</svg><div class="donut-centre"><strong>${orders.length}</strong><small>DEMO ORDERS</small></div></div>${statuses.map((s,i)=>`<button class="legend-row legend-filter" data-act="status-orders" data-status="${s}" aria-label="Filter orders by ${s}"><span><i class="legend-dot" style="background:${colors[i]}"></i>${s}</span><b>${orders.filter(o=>o.status===s).length} &nbsp;↗</b></button>`).join('')}`}
function panel(title,content,extra=''){return `<section class="dash-panel"><div class="panel-heading"><h2>${title}</h2>${extra}</div>${content}</section>`}
function table(columns,rows){return `<div class="table-wrap"><table class="admin-table"><thead><tr>${columns.map(c=>`<th>${c}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${columns.length}" class="no-data">No matching records. Use Add new to get started.</td></tr>`}</tbody></table></div>`}
function editButtons(collection,id,remove=true){return `<div class="table-actions"><button data-act="edit" data-col="${collection}" data-id="${h(id)}">Edit</button>${remove?`<button data-act="delete" data-col="${collection}" data-id="${h(id)}">Delete</button>`:''}</div>`}
function orderTable(list){return table(['Order','Customer','Date','Total','Status',''],list.map(o=>`<tr><td><strong>${h(o.id)}</strong><small>Demo order</small></td><td>${h(o.customer||'Demo customer')}</td><td>${date(o.created)}</td><td>${inr(o.total)}</td><td>${label(o.status)}</td><td><button class="btn admin-btn" data-act="order" data-id="${h(o.id)}">Manage</button></td></tr>`))}
function filtered(list){return list.filter(v=>JSON.stringify(v).toLowerCase().includes(query.toLowerCase()))}
function tools(collection,add=true){return `<div class="table-tools"><input class="table-search" id="table-search" type="search" placeholder="Search this collection…" value="${h(query)}" aria-label="Search records"><div class="workspace-tools">${add?`<button class="btn primary admin-btn" data-act="new" data-col="${collection}">+ Add new</button>`:''}<button class="btn admin-btn" data-act="export" data-col="${collection}">Export CSV ↗</button></div></div>`}
function dashboard(analytics=false){const orders=rangeOrders();return `${analytics?'':`<section class="dashboard-welcome"><div class="welcome-copy"><div class="eyebrow">THE HEALTH OF YOUR STORE</div><h2>A brighter view of your everyday.</h2><p>From your first order to your next idea, keep every part of your care business in view.</p><div class="welcome-links"><a href="#/orders">Manage orders ↗</a><a href="#/products">Explore products ↗</a></div></div><div class="welcome-art" aria-hidden="true"><span class="depth-ring"></span><span class="depth-cross"></span><span class="depth-pill"></span><span class="orb-dot"></span></div></section>`}<div class="stats-grid">${stats()}</div><div class="dashboard-grid">${panel(analytics?'Revenue over time':'Your store, at a glance.',`<div class="chart-summary"><div>Sample revenue<b>${inr(revenue(orders))}</b></div><div>Orders<b>${orders.length}</b></div></div>${lineChart()}`,'<small>Interactive overview</small>')}${panel('Order overview',donut(),'<small>Selected range</small>')}</div>${analytics?`<div class="dashboard-grid">${panel('Category performance',categoryBars())}${panel('Stock health',stockBars())}</div>`:`<div class="dashboard-grid">${panel('Recent orders',orderTable(Store.state.orders.slice(0,5)),'<a class="text-link" href="#/orders">View all ↗</a>')}${panel('Stock needs a little care.',stockBars(),'<a class="text-link" href="#/inventory">Inventory ↗</a>')}</div>`}`}
function stockBars(){return Store.state.products.slice().sort((a,b)=>a.stock-b.stock).slice(0,5).map(p=>`<div class="legend-row" style="display:block"><div style="display:flex;justify-content:space-between;gap:10px"><span>${h(p.name)}</span><b>${p.stock}</b></div><div class="mini-progress"><i style="width:${Math.min(100,p.stock)}%"></i></div></div>`).join('')}
function categoryBars(){const data={};for(const o of rangeOrders())for(const item of o.items){const c=Store.state.products.find(p=>p.id===item.id)?.category||'Other';data[c]=(data[c]||0)+item.price*item.qty}const max=Math.max(1,...Object.values(data));return Object.entries(data).map(([c,n])=>`<div class="legend-row" style="display:block"><div style="display:flex;justify-content:space-between"><span>${h(c)}</span><b>${inr(n)}</b></div><div class="mini-progress"><i style="width:${n/max*100}%"></i></div></div>`).join('')||'<p class="no-data">No category data in this range.</p>'}
function collectionRows(name){let rows=filtered(Store.state[name]);if(name==='orders'){const p=new URLSearchParams(location.hash.split('?')[1]||'');if(p.get('status'))rows=rows.filter(o=>o.status===p.get('status'));if(p.get('day'))rows=rows.filter(o=>o.created.slice(0,10)===p.get('day'));if(p.get('days'))rows=rows.filter(o=>new Date(o.created)>=Date.now()-Number(p.get('days'))*86400000)}return rows}
function collectionView(name){const s=Store.state,list=collectionRows(name);let body='';if(name==='products')body=table(['Product','SKU','Price / MRP','Stock','Visibility',''],list.map(p=>`<tr><td><div class="product-cell">${p.image?`<img src="${h(p.image)}" alt="">`:`<span class="product-letter">${h(p.name[0])}</span>`}<div><strong>${h(p.name)}</strong><small>${h(p.category)}${p.prescription?' · Rx enquiry only':''}</small></div></div></td><td>${h(p.sku)}</td><td>${inr(p.price)}<small>MRP ${inr(p.mrp)}</small></td><td>${p.stock}</td><td>${label(p.active?'Visible':'Hidden')}</td><td>${editButtons(name,p.id)}</td></tr>`));if(name==='orders')body=orderTable(list);if(name==='customers')body=table(['Customer','Email','City','Marketing consent',''],list.map(c=>`<tr><td><strong>${h(c.name)}</strong><small>Demo record</small></td><td>${h(c.email)}</td><td>${h(c.city)}</td><td>${label(c.consent?'Opted in':'Not opted in')}</td><td>${editButtons(name,c.id)}</td></tr>`));if(name==='discounts')body=table(['Code','Discount','Minimum','Expiry','Status',''],list.map(d=>`<tr><td><strong>${h(d.code)}</strong></td><td>${d.type==='percent'?h(d.value)+'%':inr(d.value)}</td><td>${inr(d.minOrder)}</td><td>${h(d.expires||'No expiry')}</td><td>${label(d.active?'Active':'Paused')}</td><td>${editButtons(name,d.id)}</td></tr>`));if(name==='campaigns')body=table(['Campaign','Channel','Audience','Schedule','Status',''],list.map(c=>`<tr><td><strong>${h(c.name)}</strong></td><td>${h(c.channel)}</td><td>${h(c.audience)}</td><td>${h(c.schedule||'Not scheduled')}</td><td>${label(c.status)}</td><td>${editButtons(name,c.id)}</td></tr>`));const orderParams=new URLSearchParams(location.hash.split('?')[1]||'');const filter=name==='orders'&&(orderParams.get('status')||orderParams.get('day'));return (filter?`<div class="filter-breadcrumb">Showing ${h(orderParams.get('status')||orderParams.get('day'))} demo orders<a href="#/orders">Clear filter ×</a></div>`:'')+panel(name==='campaigns'?'Campaign planner':name==='orders'?'All demo orders':'Manage '+name,tools(name,!['orders'].includes(name))+body)+(name==='campaigns'?'<div class="notice">Planning only. No emails, SMS or WhatsApp campaigns are sent. Connect providers and confirm consent before enabling delivery.</div>':'')}
function inventory(){return panel('Inventory control',tools('products',false)+table(['Product','SKU','Available stock','Stock status',''],filtered(Store.state.products).map(p=>`<tr><td><strong>${h(p.name)}</strong></td><td>${h(p.sku)}</td><td>${p.stock}</td><td>${label(p.stock===0?'Out of stock':p.stock<15?'Low stock':'Active')}</td><td><button class="btn admin-btn" data-act="stock" data-id="${p.id}">Adjust stock</button></td></tr>`)))}
function returnsView(){return panel('Return requests',table(['Request','Order','Reason','Amount','Status',''],Store.state.returns.map(r=>`<tr><td>${h(r.id)}</td><td>${h(r.orderId)}</td><td>${h(r.reason)}</td><td>${inr(r.amount)}</td><td>${label(r.status)}</td><td><button class="btn admin-btn" data-act="return" data-id="${h(r.id)}">Review</button></td></tr>`)))+'<div class="notice">Refunds here update demo records only. No real payment refunds occur. Stock restoration is guarded against duplicates.</div>'}
function visitors(){const sessions=Store.state.sessions.filter(s=>Date.now()-new Date(s.at)<90000);return `<div class="stats-grid"><article class="stat-card"><div class="stat-top">Active browser sessions <span class="live-dot"></span></div><strong>${sessions.length}</strong><small>Seen in the last 90 seconds</small></article><article class="stat-card"><div class="stat-top">Recorded events</div><strong>${Store.state.events.length}</strong><small>Visits and interactions, not seeded traffic</small></article></div>${panel('Visitors right now',table(['Session (anonymous)','Page','Device','Last seen'],sessions.map(s=>`<tr><td>${h(s.id.slice(0,8))}…</td><td>${h(s.path)}</td><td>${h(s.device)}</td><td>${new Date(s.at).toLocaleTimeString()}</td></tr>`)),'<span class="small"><i class="live-dot"></i>Refreshes every 20s</span>')}<div class="notice">${Store.server?'Server-observed demo sessions.':'Browser-local preview: this shows visits from storefront tabs in this browser only. Shared live traffic requires the Node backend.'} No invented visitor counts are shown.</div>`}
function behaviour(){const steps=[['Store visits','view'],['Product views','product'],['Added to basket','add_to_cart'],['Checkout visits','checkout'],['Demo purchases','purchase']],max=Math.max(1,...steps.map(([,type])=>Store.state.events.filter(e=>e.type===type).length));return `<div class="dashboard-grid">${panel('Customer journey',steps.map(([title,type])=>{const n=Store.state.events.filter(e=>e.type===type).length;return `<div class="funnel-row"><div><span>${title}</span><strong>${n}</strong></div><div class="funnel-track"><div class="funnel-fill" style="width:${n/max*100}%"></div></div></div>`}).join(''))}${panel('Recent interactions',table(['Event','Page','Time'],Store.state.events.filter(e=>e.type!=='heartbeat').slice(0,12).map(e=>`<tr><td>${h(e.type)}</td><td>${h(e.path)}</td><td>${new Date(e.at).toLocaleTimeString()}</td></tr>`)))}</div><div class="notice">Recorded demo interactions only. Counts are events, not unique customers or conversion rates.</div>`}
function calendarView(){const first=new Date(year,month,1),days=new Date(year,month+1,0).getDate(),prefix=Array.from({length:first.getDay()},()=>'<div class="calendar-day blank"></div>').join('');return panel('Care calendar',`<div class="calendar-toolbar"><button class="btn admin-btn" data-act="prev-month">←</button><h2>${first.toLocaleDateString('en-IN',{month:'long',year:'numeric'})}</h2><button class="btn admin-btn" data-act="next-month">→</button><button class="btn primary admin-btn" data-act="new" data-col="calendar">+ Event</button></div><div class="calendar-grid">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<div class="calendar-weekday">${d}</div>`).join('')}${prefix}${Array.from({length:days},(_,i)=>{const day=year+'-'+String(month+1).padStart(2,'0')+'-'+String(i+1).padStart(2,'0');return `<div class="calendar-day ${day===new Date().toISOString().slice(0,10)?'today':''}">${i+1}${Store.state.calendar.filter(e=>e.date===day).map(e=>`<button class="calendar-event" data-act="edit" data-col="calendar" data-id="${h(e.id)}" title="${h(e.title)}">${h(e.title)}</button>`).join('')}</div>`}).join('')}</div>`)+panel('Upcoming & saved events',table(['Event','Date','Type',''],Store.state.calendar.map(e=>`<tr><td>${h(e.title)}</td><td>${h(e.date)}</td><td>${h(e.type)}</td><td>${editButtons('calendar',e.id)}</td></tr>`)))}
function bannersView(){return panel('Landscape banners',tools('banners')+`<div class="media-grid">${filtered(Store.state.banners).map((b,i)=>`<article class="media-card"><div class="media-preview">${b.image?`<img src="${h(b.image)}" alt="${h(b.title)}">`:''}</div><div class="media-info"><h3>${h(b.title)}</h3><p>${h(b.placement)} · ${b.active?'Visible':'Hidden'} · Landscape on all screens</p>${editButtons('banners',b.id)}<div class="table-actions"><button data-act="move-banner" data-id="${b.id}" data-dir="-1">Move up ↑</button><button data-act="move-banner" data-id="${b.id}" data-dir="1">Move down ↓</button></div></div></article>`).join('')}</div>`)}
function mediaView(images=false){return panel(images?'Image assignments':'Your photo library',`<div class="table-tools"><p class="small">PNG, JPG or WebP · Maximum 2 MB per upload</p><label class="media-upload"><span class="btn primary admin-btn">+ Upload image</span><input id="media-upload" type="file" accept="image/png,image/jpeg,image/webp" aria-label="Upload image"></label></div><div class="media-grid">${Store.state.media.map(m=>`<article class="media-card"><div class="media-preview"><img src="${h(m.url)}" alt="${h(m.name)}"></div><div class="media-info"><h3>${h(m.name)}</h3><p>${h(m.role||'Library image')}</p><div class="table-actions"><button data-act="copy" data-url="${h(m.url)}">Copy URL</button><button data-act="assign" data-id="${h(m.id)}">Assign</button><button data-act="media-delete" data-id="${h(m.id)}">Delete</button></div></div></article>`).join('')}</div>`)+(images?'<div class="notice">Assign any image to the logo, a product, or a banner. Changes reflect in the storefront. Referenced images must be unassigned before deletion.</div>':'')}
function field([key,title,type,options],value){if(type==='checkbox')return `<label class="checkbox"><input type="checkbox" name="${key}" ${value?'checked':''}><span>${title}</span></label>`;if(type==='textarea')return `<label class="field full">${title}<textarea name="${key}" maxlength="5000">${h(value||'')}</textarea></label>`;if(type==='select')return `<label class="field">${title}<select name="${key}">${options.map(v=>`<option ${value===v?'selected':''}>${h(v)}</option>`).join('')}</select></label>`;if(type==='image')return `<label class="field full">${title}<input name="${key}" value="${h(value||'')}" placeholder="assets/image.webp or https://…"><input type="file" data-image-field="${key}" accept="image/png,image/jpeg,image/webp"><small>Upload or paste an image URL. Uploaded file replaces this field.</small></label>`;return `<label class="field">${title}<input name="${key}" type="${type}" ${type==='number'?'min="0" step="1"':''} ${['date','image'].includes(type)||title.includes('optional')?'':'required'} value="${h(value??'')}" maxlength="500"></label>`}
function settingsView(editor=false){const s=Store.state.settings;const groups=editor?[
['Homepage hero',[['heroTitle','Headline','text'],['heroSubtitle','Supporting text','textarea'],['heroButton','Button text','text'],['heroLink','Button destination','text']]],
['Sections & visibility',[['showCategories','Show categories','checkbox'],['showFeatured','Show featured products','checkbox'],['showPromos','Show promotional banners','checkbox'],['showJournal','Show care journal','checkbox'],['showHow','Show how it works','checkbox'],['showPrescription','Show prescription assistance','checkbox'],['showCta','Show closing call to action','checkbox'],['showServices','Show pharmacy service shortcuts','checkbox'],['showComparison','Show home medicine comparison','checkbox'],['showOffers','Show home offers','checkbox']]],
['Brand & appearance',[['brandName','Store name','text'],['tagline','Tagline','text'],['logo','Transparent logo URL','image'],['primary','Primary colour (hex)','text'],['background','Background colour (hex)','text'],['topline','Top strip text','text']]]]:[
['Delivery areas',[['serviceablePincodes','Serviceable Indian pincodes (comma or space separated; leave blank if not confirmed)','textarea']]],
['Commerce',[['shippingFee','Shipping fee (₹)','number'],['freeShippingThreshold','Free shipping from (₹)','number']]],
['Business contact',[['contactEmail','Support email (optional)','email'],['contactPhone','Phone (optional)','text'],['address','Registered address','textarea'],['licence','Pharmacy licence details (optional)','text']]],
['Connections',[['whatsappNumber','WhatsApp business number with country code (for chat & quotations)','text'],['googleClientId','Google client ID (optional; not auth integration)','text']]]];return `<form id="settings-form" class="admin-form"><div class="settings-grid">${groups.map(([title,fields])=>`<section class="setting-card"><h2>${title}</h2>${fields.map(f=>field(f,s[f[0]])).join('')}</section>`).join('')}${editor?`<section class="setting-card"><h2>Page & section copy</h2>${Object.entries(Store.state.pages).map(([key,value])=>`<label class="field">${h(key)}<textarea name="page:${key}" maxlength="5000">${h(value)}</textarea></label>`).join('')}</section>`:`<section class="setting-card"><h2>Platform status</h2><p>Environment: <b>${Store.server?'Node API demo':'Browser-local demo'}</b></p><p>Database: <b>Not connected</b></p><p>Payments / Google OAuth: <b>Not connected</b></p><p>WhatsApp: <b>${s.whatsappNumber?'Configured handoff link':'Not configured'}</b></p><div class="notice">These fields configure the storefront. Saving a Google client ID alone does not enable secure Google authentication.</div><button type="button" class="btn admin-btn" data-act="export-json">Export workspace JSON</button></section>`}</div><div class="save-bar"><a class="btn admin-btn" href="./" target="_blank" rel="noopener">Preview store ↗</a><button class="btn primary admin-btn" type="submit">Save ${editor?'store editor':'settings'}</button></div></form>${editor?panel('Navigation menu',`<button class="btn primary admin-btn" data-act="new" data-col="navigation">+ Add menu item</button>`+table(['Label','Destination','Visibility',''],Store.state.navigation.map(n=>`<tr><td>${h(n.label)}</td><td>${h(n.href)}</td><td>${label(n.active?'Visible':'Hidden')}</td><td>${editButtons('navigation',n.id)}</td></tr>`)))+panel('Shop categories',`<button class="btn primary admin-btn" data-act="new" data-col="categories">+ Add category</button>`+table(['Category','Key','Visibility',''],Store.state.categories.map(c=>`<tr><td>${h(c.name)}</td><td>${h(c.id)}</td><td>${label(c.active?'Visible':'Hidden')}</td><td>${editButtons('categories',c.id)}</td></tr>`))):''}`}
function prescriptionDesk(){return panel('Prescription review & quotation desk',`<div class="notice">Manual demo review only. A document upload never establishes authenticity, a valid prescription or permission to dispense. Use sample documents.</div>`+table(['Request','Alias / notes','Submitted','Status','Quoted total',''],Store.state.prescriptions.map(r=>`<tr><td><strong>${h(r.id)}</strong><small>${r.document?.name?h(r.document.name):'Sample document'}</small></td><td><strong>${h(r.patientAlias)}</strong><small>${h(r.notes)}</small></td><td>${date(r.created)}</td><td>${label(r.status)}</td><td>${inr(PharmacyCore.quoteTotal(r))}</td><td><button class="btn primary admin-btn" data-act="review-prescription" data-id="${h(r.id)}">Review & quote</button></td></tr>`)))}
function prescriptionReview(id){const r=Store.state.prescriptions.find(r=>r.id===id);if(!r)return;const documentUrl=Store.server?'/api/prescriptions/'+encodeURIComponent(id)+'/document':r.document?.data;const selected=Store.state.products.filter(p=>p.active);dialog(`<h2>Review ${h(r.id)}</h2><p>${h(r.patientAlias)} · ${h(r.notes)}</p><div class="rx-review-document">${r.document?.mime?.startsWith('image/')?`<img src="${h(documentUrl)}" alt="Sample prescription for review">`:''}<a class="btn admin-btn" href="${h(documentUrl||'')}" ${Store.server?'':'download="sample-prescription.pdf"'} target="_blank" rel="noopener">Open sample document ↗</a><small>Use the prescriber and patient information in the sample to practise your team checks. No automated real/fake verdict is provided.</small></div><form id="rx-review-form" data-id="${h(id)}"><h3>Manual review record</h3><div class="review-checks">${[['prescriber','Prescriber details checked'],['date','Prescription date / validity checked'],['legible','Document legibility and medicine details checked'],['suitability','Patient suitability and substitution review recorded']].map(([key,title])=>`<label class="checkbox"><input type="checkbox" name="${key}" ${r.review?.[key]?'checked':''}>${title}</label>`).join('')}</div><div class="form-grid"><label class="field">Review outcome<select name="authenticity">${['Unreviewed','Needs verification','Concerns identified','Manual review recorded'].map(v=>`<option ${r.review?.authenticity===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Reviewer name / demo ID<input name="reviewer" value="${h(r.review?.reviewer||'')}" maxlength="100"></label></div><label class="field">Internal review notes<textarea name="reviewNotes" maxlength="2000">${h(r.review?.notes||'')}</textarea></label><label class="field">Request status<select name="status">${PharmacyCore.rxStatuses.filter(s=>!['Accepted','Demo order created'].includes(s)||s===r.status).map(s=>`<option ${r.status===s?'selected':''}>${s}</option>`).join('')}</select></label><h3>Itemised quotation</h3><div id="rx-quote-lines">${(r.lines.length?r.lines:[{id:'',qty:1,unitPrice:0}]).map((line,index)=>rxQuoteLine(selected,line,index)).join('')}</div><button class="btn admin-btn" type="button" data-act="add-rx-line">+ Add quote line</button><div class="form-grid" style="margin-top:15px"><label class="field">Quote valid until<input name="quoteExpiry" type="date" value="${h(r.quoteExpiry)}" min="${new Date().toISOString().slice(0,10)}"></label><label class="field">Customer-facing quotation / clarification note<textarea name="quoteNote" maxlength="2000">${h(r.quoteNote||'')}</textarea></label></div><p class="small">Quote line prices are per pack. A completed manual review is required before approval. The customer accepts an unexpired quote; stock is checked again before a demo order is created.</p><p id="rx-review-error" class="login-error" role="alert"></p><button class="btn primary block">Save review & quotation</button></form>`)}
function rxQuoteLine(products,line,index){return `<div class="rx-quote-line"><label class="field">Medicine<select name="rxProduct"><option value="">No item</option>${products.map(p=>`<option value="${p.id}" data-price="${p.price}" ${line.id===p.id?'selected':''}>${h(p.name)} · ${p.packUnits||1} units / pack</option>`).join('')}</select></label><label class="field">Packs<input name="rxQty" type="number" min="1" max="20" value="${line.qty||1}"></label><label class="field">Price / pack<input name="rxPrice" type="number" min="0" max="1000000" step="0.01" value="${line.unitPrice||0}"></label><button type="button" class="rx-remove-line" data-act="remove-rx-line" aria-label="Remove quote line">×</button></div>`}
function consultationDesk(){return panel('Consultation requests',table(['Request / service','Alias','Preferred date / time','Status','Assigned clinician',''],Store.state.appointments.map(a=>`<tr><td><strong>${h(a.id)}</strong><small>${h(a.serviceName)}</small></td><td>${h(a.patientAlias)}</td><td>${h(a.date)}<small>${h(a.time)} IST</small></td><td>${label(a.status)}</td><td>${h(a.assignedClinician||'Unassigned')}</td><td><button class="btn admin-btn" data-act="manage-consultation" data-id="${h(a.id)}">Manage request</button></td></tr>`)))+'<div class="notice">Demo service requests only. No real clinician, video call, consultation payment or clinical advice is provided by this platform preview.</div>'}
function manageConsultation(id){const a=Store.state.appointments.find(a=>a.id===id);dialog(`<h2>${h(a.serviceName)}</h2><p>${h(a.id)} · ${h(a.patientAlias)}</p><p>${h(a.notes||'No sample notes')}</p><form id="manage-consultation-form" data-id="${h(id)}"><label class="field">Request status<select name="status">${['Requested','Needs clarification','Scheduled','Completed','Cancelled'].map(s=>`<option ${a.status===s?'selected':''}>${s}</option>`).join('')}</select></label><div class="form-grid"><label class="field">Confirmed date<input name="date" type="date" required value="${h(a.date)}"></label><label class="field">Time (India time)<select name="time">${['09:00','11:00','14:00','16:00'].map(t=>`<option ${a.time===t?'selected':''}>${t}</option>`).join('')}</select></label></div><label class="field">Assigned clinician / demo assignment<input name="assignedClinician" maxlength="150" value="${h(a.assignedClinician||'')}" placeholder="Use demo assignment text only"></label><label class="field">Customer-facing note<textarea name="teamNote" maxlength="2000">${h(a.teamNote||'')}</textarea></label><label class="field">Meeting instructions (demo text)<textarea name="meetingNote" maxlength="2000">${h(a.meetingNote||'')}</textarea></label><button class="btn primary block">Save consultation request</button></form>`)}
function pharmacyContentDesk(col){const rows=Store.state[col];return panel(col==='offers'?'Store offers':'Consultation services',`<button class="btn primary admin-btn" data-act="new" data-col="${col}">+ Add ${col==='offers'?'offer':'service'}</button>`+table(col==='offers'?['Offer','Coupon','Visibility','']:['Service','Fee','Duration','Visibility',''],rows.map(v=>`<tr><td><strong>${h(v.title||v.name)}</strong><small>${h(v.description)}</small></td>${col==='offers'?`<td>${h(v.code||'No coupon')}</td>`:`<td>${inr(v.fee)}</td><td>${v.duration} min</td>`}<td>${label(v.active?'Visible':'Hidden')}</td><td>${editButtons(col,v.id)}</td></tr>`)))}
function login(){A.innerHTML=`<main class="admin-login"><div class="panel"><img src="${h(Store.state.settings.logo)}" alt="${h(Store.state.settings.brandName)}"><div class="eyebrow">Your care workspace</div><h1>A little clarity.<br>A lot of control.</h1><p>Sign in to manage your storefront, products and everyday operations.</p>${!Store.server?'<div class="demo-credentials"><b>Private preview credentials</b><br>ID: <code>demo@trustedmeds.local</code><br>Password: <code>TrustedMeds@2026</code></div>':'<div class="notice">Authenticated Node backend · Demo commerce</div>'}<form id="login-form"><label class="field">Admin ID<input type="email" name="email" required autocomplete="username" value="${Store.server?'':'demo@trustedmeds.local'}"></label><label class="field">Password<input type="password" name="password" required autocomplete="current-password" ${Store.server?'':'value="TrustedMeds@2026"'}></label><p id="login-error" class="login-error"></p><button class="btn primary block">Open workspace →</button></form><div class="login-footer"><a href="./">← Back to store</a><span>${Store.server?'Server authenticated':'Browser-local preview'}</span></div></div></main>`}
function render(){if(!Store.isAdmin)return login();const previousNavScroll=document.getElementById('admin-header-tabs')?.scrollLeft||0;const p=NAV.flatMap(g=>g[1]).some(n=>n[0]===page())?page():'dashboard',item=NAV.flatMap(g=>g[1]).find(n=>n[0]===p)||NAV[0][1][0],name=item[1];let body=p==='dashboard'?dashboard():p==='analytics'?dashboard(true):p==='visitors'?visitors():p==='behaviour'?behaviour():p==='calendar'?calendarView():p==='prescriptions'?prescriptionDesk():p==='appointments'?consultationDesk():p==='consultations'||p==='offers'?pharmacyContentDesk(p):p==='inventory'?inventory():p==='returns'?returnsView():p==='banners'?bannersView():p==='media'||p==='images'?mediaView(p==='images'):p==='editor'||p==='settings'?settingsView(p==='editor'):p==='audit'?panel('Workspace activity',Store.state.audit.map(a=>`<div class="audit-item"><small>${new Date(a.at).toLocaleString()}</small><span>${h(a.action)}</span></div>`).join('')):collectionView(p==='marketing'?'campaigns':p);A.innerHTML=`<div class="sidebar-scrim" data-act="menu"></div><div class="admin-layout"><aside class="admin-sidebar"><a href="#/dashboard" class="brand admin-brand"><img src="${h(Store.state.settings.logo)}" alt="${h(Store.state.settings.brandName)}"></a><nav aria-label="Admin navigation">${NAV.map(([group,links])=>`<div class="nav-group">${group}</div>${links.map(([key,title,ico])=>`<a href="#/${key}" class="${key===p?'active':''}"><span>${ico}</span>${title}</a>`).join('')}`).join('')}</nav><div class="sidebar-end"><b><i class="live-dot"></i>${Store.server?'Node API connected':'Private demo workspace'}</b><small>TrustedMeds · Platform v2</small></div></aside><div class="admin-right"><header class="admin-top"><div class="admin-top-left"><button class="admin-mobile-menu" data-act="menu" aria-label="Toggle admin navigation" aria-expanded="false">☰</button><div><strong>TrustedMeds / ${name}</strong><small>Thoughtful care. Thoughtful operations.</small></div></div><div class="top-actions"><a class="btn admin-btn" href="./" target="_blank" rel="noopener">View store ↗</a><button class="btn admin-btn" data-act="logout">Sign out</button><span class="admin-avatar">TM</span></div>${TMHeaderNav.admin(NAV,p)}</header><main class="admin-main" id="admin-main"><div class="workspace-head"><div><div class="eyebrow">${p==='dashboard'?'Your everyday, at a glance':'Your care workspace'}</div><h1>${p==='dashboard'?'Good things start with clarity.':name+'.'}</h1><p>${p==='dashboard'?'A calm overview of your store, so you can focus on what matters.':'Manage '+name.toLowerCase()+' from one connected workspace.'}</p></div><div class="workspace-tools"><button class="btn admin-btn" data-act="refresh">↻ Refresh</button>${['dashboard','analytics'].includes(p)?`<select id="period" class="admin-select" aria-label="Analytics period"><option value="7" ${period===7?'selected':''}>Last 7 days</option><option value="30" ${period===30?'selected':''}>Last 30 days</option></select>`:''}</div></div><div class="demo-banner"><b>DEMO WORKSPACE</b><span>${Store.server?'Server-backed demo. No live payments or dispatch.':'Changes control the storefront in this browser. Database and production services are not connected.'}</span></div>${body}</main></div></div>`;TMHeaderNav.revealAdmin(document.getElementById('admin-header-tabs'),previousNavScroll)}
function openEditor(col,id){const item=Store.state[col].find(v=>v.id===id)||{},schema=col==='products'?SCHEMAS.products.map(f=>f[0]==='category'?[...f.slice(0,3),Store.state.categories.map(c=>c.id)]:f):SCHEMAS[col];if(!schema)return;uploaded='';dialog(`<h2>${id?'Edit':'Add'} ${col==='products'?'product':col==='calendar'?'event':col.replace(/s$/,'')}</h2><form class="admin-form" id="collection-form" data-col="${col}" data-id="${h(id||'')}"><div class="form-grid">${schema.map(f=>field(f,item[f[0]]??(f[2]==='checkbox'?true:f[2]==='number'?(f[0]==='packUnits'?1:f[0]==='duration'?20:0):f[2]==='select'?f[3][0]:''))).join('')}</div><p id="form-error" class="login-error"></p><button class="btn primary block">Save changes</button></form>`);if(id&&col==='products')eb.querySelector('[name=id]').readOnly=true}
function download(name,content,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function commit(fn,action){await Store.commit(fn,action);render();notify('Saved. Storefront updated.');}
document.addEventListener('click',async event=>{const b=event.target.closest('[data-act]');if(!b)return;const {act,id,col}=b.dataset;try{if(act==='review-prescription')prescriptionReview(id);if(act==='manage-consultation')manageConsultation(id);if(act==='add-rx-line'){document.getElementById('rx-quote-lines').insertAdjacentHTML('beforeend',rxQuoteLine(Store.state.products.filter(p=>p.active),{id:'',qty:1,unitPrice:0},0))}if(act==='remove-rx-line')b.closest('.rx-quote-line').remove();if(act==='chart-mode'){chartMode=b.dataset.mode==='bars'?'bars':'line';render()}if(act==='chart-day')location.hash='/orders?day='+encodeURIComponent(b.dataset.day);if(act==='status-orders')location.hash='/orders?status='+encodeURIComponent(b.dataset.status)+'&days='+period;if(act==='stat-go')location.hash='/'+b.dataset.route;if(act==='close')E.close();if(act==='menu'){document.querySelector('.admin-sidebar').classList.toggle('open');document.querySelector('.sidebar-scrim').classList.toggle('open');const toggle=document.querySelector('.admin-mobile-menu');toggle?.setAttribute('aria-expanded',String(document.querySelector('.admin-sidebar').classList.contains('open')))}if(act==='logout'){await Store.logout();render()}if(act==='refresh'){await Store.refresh();render();notify('Workspace refreshed.')}if(act==='new'||act==='edit')openEditor(col,id);if(act==='delete'){dialog(`<h2>Delete this record?</h2><p>This removes it from the demo workspace and any storefront listing.</p><button class="btn primary block" data-act="confirm-delete" data-col="${col}" data-id="${h(id)}">Delete record</button>`)}if(act==='confirm-delete'){await commit(s=>{if(col==='consultations'&&s.appointments.some(a=>a.serviceId===id)){s.consultations.find(c=>c.id===id).active=false;}else if(col==='products'&&s.orders.some(o=>o.items.some(p=>p.id===id))){s.products.find(p=>p.id===id).active=false;}else s[col]=s[col].filter(v=>v.id!==id)},'Removed '+col+' '+id);E.close()}if(act==='stock'){const p=Store.state.products.find(p=>p.id===id);dialog(`<h2>Adjust ${h(p.name)}</h2><form id="stock-form" data-id="${id}"><label class="field">Available stock<input type="number" name="stock" min="0" max="1000000" required value="${p.stock}"></label><button class="btn primary block">Save stock</button></form>`)}if(act==='order'){const o=Store.state.orders.find(o=>o.id===id);dialog(`<h2>${h(o.id)}</h2><p>Demo order · ${inr(o.total)} · No live payment</p>${o.items.map(p=>`<p>${h(p.name)} × ${p.qty} · ${inr(p.price*p.qty)}</p>`).join('')}<form id="order-form" data-id="${h(id)}"><label class="field">Status<select name="status">${['Pending','Processing','Shipped','Delivered','Cancelled','Refunded'].map(s=>`<option ${o.status===s?'selected':''}>${s}</option>`).join('')}</select></label><p class="small">Cancelled / refunded orders restore stock once. Terminal statuses cannot be reopened.</p><button class="btn primary block">Update demo order</button></form>`)}if(act==='return'){const r=Store.state.returns.find(r=>r.id===id);dialog(`<h2>Review ${h(r.id)}</h2><p>${h(r.reason)}</p><form id="return-form" data-id="${h(id)}"><label class="field">Decision<select name="status">${['Requested','Approved','Rejected','Refunded'].map(s=>`<option ${r.status===s?'selected':''}>${s}</option>`).join('')}</select></label><p class="small">Refunded marks the linked demo order refunded and restores its stock once. No money is transferred.</p><button class="btn primary block">Save decision</button></form>`)}if(act==='prev-month'||act==='next-month'){month+=act==='next-month'?1:-1;if(month<0){month=11;year--}if(month>11){month=0;year++}render()}if(act==='move-banner')await commit(s=>{const i=s.banners.findIndex(x=>x.id===id),j=i+Number(b.dataset.dir);if(j>=0&&j<s.banners.length)[s.banners[i],s.banners[j]]=[s.banners[j],s.banners[i]]},'Reordered banners');if(act==='copy'){try{await navigator.clipboard.writeText(b.dataset.url);notify('Image URL copied.')}catch{dialog(`<h2>Image URL</h2><label class="field"><input readonly value="${h(b.dataset.url)}"></label>`)}}if(act==='media-delete'){const m=Store.state.media.find(m=>m.id===id),s=Store.state;if(s.settings.logo===m.url||s.products.some(p=>p.image===m.url)||s.banners.some(p=>p.image===m.url))throw Error('This image is assigned. Change its logo, product or banner assignment first.');await commit(s=>s.media=s.media.filter(x=>x.id!==id),'Removed library image')}if(act==='assign'){dialog(`<h2>Assign this image</h2><form id="assign-form" data-id="${h(id)}"><label class="field">Use image for<select name="target"><option value="logo">Store logo</option>${Store.state.banners.map(v=>`<option value="banner:${h(v.id)}">Banner: ${h(v.title)}</option>`).join('')}${Store.state.products.map(v=>`<option value="product:${h(v.id)}">Product: ${h(v.name)}</option>`).join('')}</select></label><button class="btn primary block">Assign image</button></form>`)}if(act==='export'){const rows=collectionRows(col),keys=[...new Set(rows.flatMap(Object.keys))].filter(k=>!['items','image'].includes(k)),csv=[keys.join(','),...rows.map(r=>keys.map(k=>'"'+String(r[k]??'').replace(/"/g,'""').replace(/^[=+@-]/,"'$&")+'"').join(','))].join('\n');download('trustedmeds-'+col+'.csv',csv,'text/csv')}if(act==='export-json')download('trustedmeds-workspace.json',JSON.stringify(Store.state,null,2),'application/json');}catch(e){notify(e.message)}});
document.addEventListener('submit',async event=>{const f=event.target;if(!f.id)return;event.preventDefault();if(!f.reportValidity())return;const values=Object.fromEntries(new FormData(f));const submit=f.querySelector('button[type=submit],button:not([type])');if(submit)submit.disabled=true;try{if(f.id==='rx-review-form'){try{await commit(s=>{const r=s.prescriptions.find(r=>r.id===f.dataset.id);if(r.orderId)throw Error('An accepted quotation cannot be edited.');r.review={prescriber:f.elements.prescriber.checked,date:f.elements.date.checked,legible:f.elements.legible.checked,suitability:f.elements.suitability.checked,reviewer:values.reviewer.trim(),authenticity:values.authenticity,notes:values.reviewNotes};r.status=values.status;r.lines=[...f.querySelectorAll('.rx-quote-line')].map(row=>({id:row.querySelector('[name=rxProduct]').value,qty:Number(row.querySelector('[name=rxQty]').value),unitPrice:Number(row.querySelector('[name=rxPrice]').value)})).filter(line=>line.id);r.quoteExpiry=values.quoteExpiry;r.quoteNote=values.quoteNote;},'Prescription review / quote updated');E.close()}catch(error){document.getElementById('rx-review-error').textContent=error.message}return}if(f.id==='manage-consultation-form'){await commit(s=>{const a=s.appointments.find(a=>a.id===f.dataset.id);if(['Scheduled','Completed'].includes(values.status)&&!values.assignedClinician.trim())throw Error('Record a demo clinician assignment before confirming.');Object.assign(a,{status:values.status,date:values.date,time:values.time,assignedClinician:values.assignedClinician,teamNote:values.teamNote,meetingNote:values.meetingNote})},'Consultation request updated');E.close();return}if(f.id==='login-form'){await Store.login(values.email.trim(),values.password);render()}if(f.id==='collection-form'){const col=f.dataset.col,old=Store.state[col].find(v=>v.id===f.dataset.id),obj={...old};for(const[key,,type]of SCHEMAS[col])obj[key]=type==='checkbox'?f.elements[key].checked:type==='number'?Number(values[key]):values[key]?.trim()||'';if(col==='products'){obj.type=obj.type||'bottle';obj.color=obj.color||'#638abb';obj.label=obj.label||'DAILY';obj.sub=obj.sub||'WELLNESS'}if(col==='discounts'){obj.code=obj.code.toUpperCase();if(obj.value<=0||(obj.type==='percent'&&obj.value>100))throw Error('Percentage must be 1–100; fixed discount must be positive.');if(Store.state.discounts.some(d=>d.code===obj.code&&d.id!==old?.id))throw Error('Coupon code already exists')}if(!obj.id)obj.id=f.dataset.id||crypto.randomUUID();await commit(s=>{const i=s[col].findIndex(v=>v.id===f.dataset.id);if(i>=0)s[col][i]=obj;else s[col].push(obj);if(col==='banners'&&obj.placement==='hero'){s.settings.heroTitle=obj.title;s.settings.heroSubtitle=obj.subtitle;s.settings.heroLink=obj.link}},'Updated '+col+': '+(obj.name||obj.title||obj.code||obj.label));E.close()}if(f.id==='stock-form'){await commit(s=>s.products.find(p=>p.id===f.dataset.id).stock=Number(values.stock),'Adjusted stock');E.close()}if(f.id==='order-form'){await commit(s=>{const o=s.orders.find(o=>o.id===f.dataset.id);if(['Cancelled','Refunded'].includes(o.status)&&o.status!==values.status)throw Error('Terminal orders cannot be reopened.');o.status=values.status;if(['Cancelled','Refunded'].includes(o.status)&&!o.restocked){for(const item of o.items){const p=s.products.find(p=>p.id===item.id);if(p)p.stock+=item.qty}o.restocked=true}},'Updated demo order '+f.dataset.id);E.close()}if(f.id==='return-form'){await commit(s=>{const r=s.returns.find(r=>r.id===f.dataset.id);if(r.status==='Refunded'&&values.status!=='Refunded')throw Error('Refunded return cannot be reopened.');r.status=values.status;if(r.status==='Refunded'){const o=s.orders.find(o=>o.id===r.orderId);if(o){o.status='Refunded';if(!o.restocked){for(const item of o.items){const p=s.products.find(p=>p.id===item.id);if(p)p.stock+=item.qty}o.restocked=true}}r.restocked=true}},'Updated return '+f.dataset.id);E.close()}if(f.id==='settings-form'){await commit(s=>{for(const[key,value]of Object.entries(values)){if(key.startsWith('page:'))s.pages[key.slice(5)]=value;else s.settings[key]=key==='whatsappNumber'?String(value).replace(/[+\s()-]/g,''):['shippingFee','freeShippingThreshold'].includes(key)?Number(value):value}for(const input of f.querySelectorAll('input[type=checkbox]'))s.settings[input.name]=input.checked;if(!TMCore.safeLink(s.settings.heroLink))throw Error('Invalid hero link');const hero=s.banners.find(b=>b.placement==='hero'&&b.active);if(hero){hero.title=s.settings.heroTitle;hero.subtitle=s.settings.heroSubtitle;hero.link=s.settings.heroLink}},'Saved store configuration')}if(f.id==='assign-form'){const media=Store.state.media.find(m=>m.id===f.dataset.id),[kind,id]=values.target.split(':');await commit(s=>{if(kind==='logo')s.settings.logo=media.url;else s[kind==='banner'?'banners':'products'].find(x=>x.id===id).image=media.url},'Assigned '+media.name);E.close()}}catch(e){const err=document.getElementById(f.id==='login-form'?'login-error':'form-error');if(err)err.textContent=e.message;else notify(e.message)}finally{if(submit)submit.disabled=false}});
document.addEventListener('change',async event=>{const e=event.target;try{if(e.name==='rxProduct'){const option=e.selectedOptions[0];e.closest('.rx-quote-line').querySelector('[name=rxPrice]').value=option.dataset.price||0}if(e.id==='chart-metric'){metric=e.value==='orders'?'orders':'revenue';render()}if(e.id==='period'){period=Number(e.value);render()}if(e.matches('[data-image-field]')&&e.files[0]){const url=await Store.upload(e.files[0]);e.form.elements[e.dataset.imageField].value=url;notify('Image uploaded. Save the form to apply.')}if(e.id==='media-upload'&&e.files[0]){const file=e.files[0],url=await Store.upload(file);await commit(s=>s.media.unshift({id:crypto.randomUUID(),name:file.name,url,role:'Library image'}),'Uploaded '+file.name)}}catch(error){notify(error.message)}});
document.addEventListener('input',e=>{if(e.target.id==='table-search'){query=e.target.value;const start=e.target.selectionStart;render();const input=document.getElementById('table-search');input?.focus()}});
window.addEventListener('hashchange',()=>{query='';render()});window.addEventListener('tm-store-change',()=>{if(!E.open&&Store.isAdmin&&page()!=='editor'&&page()!=='settings')render()});
(async()=>{await Store.init();await Store.resume();render();setInterval(async()=>{if(Store.isAdmin&&['visitors','behaviour'].includes(page())&&!E.open){await Store.refresh();render()}},20000)})();
